**1. Popular Node.js Rate Limiting Libraries:**

**express-rate-limit (Most Popular):**
```javascript
const rateLimit = require('express-rate-limit');

// Basic rate limiter
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in headers
  legacyHeaders: false, // Disable X-RateLimit-* headers
});

// Apply to all requests
app.use(limiter);
```

**2. Different Limits for Different Endpoints:**

```javascript
const express = require('express');
const rateLimit = require('express-rate-limit');
const app = express();

// Strict limit for login
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // 5 attempts
  message: 'Too many login attempts. Please try again in 15 minutes.',
  skipSuccessfulRequests: true, // Don't count successful logins
});

// Moderate limit for form submissions
const formLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 30,
  message: 'Too many submissions. Please try again later.',
});

// Lenient limit for general API
const apiLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 1000,
  message: 'API rate limit exceeded.',
});

// Apply to specific routes
app.post('/login', loginLimiter, (req, res) => {
  // Login logic
});

app.post('/submit-form', formLimiter, (req, res) => {
  // Form handling logic
});

app.use('/api/', apiLimiter);
```

**3. Redis-Based Rate Limiting (For Production/Multiple Servers):**

```javascript
const rateLimit = require('express-rate-limit');
const RedisStore = require('rate-limit-redis');
const Redis = require('ioredis');

// Create Redis client
const redisClient = new Redis({
  host: process.env.REDIS_HOST || 'localhost',
  port: process.env.REDIS_PORT || 6379,
  password: process.env.REDIS_PASSWORD,
});

// Rate limiter with Redis store
const limiter = rateLimit({
  store: new RedisStore({
    client: redisClient,
    prefix: 'rate_limit:', // Key prefix in Redis
  }),
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests, please try again later.',
});

app.use(limiter);
```

**4. Custom Rate Limiting Logic:**

```javascript
const Redis = require('ioredis');
const redis = new Redis();

async function customRateLimit(req, res, next) {
  const identifier = req.ip; // or req.user.id for authenticated users
  const action = req.path;
  const key = `rate_limit:${action}:${identifier}`;

  try {
    // Get current count
    const current = await redis.get(key);
    const count = current ? parseInt(current) : 0;

    // Define limits per action
    const limits = {
      '/login': { max: 5, window: 900 }, // 5 per 15 min
      '/submit-form': { max: 30, window: 3600 }, // 30 per hour
      'default': { max: 100, window: 3600 }
    };

    const limit = limits[action] || limits.default;

    // Check if limit exceeded
    if (count >= limit.max) {
      const ttl = await redis.ttl(key);
      res.set('Retry-After', ttl);
      return res.status(429).json({
        error: 'Too many requests',
        message: `Please try again in ${Math.ceil(ttl / 60)} minutes`,
        retryAfter: ttl
      });
    }

    // Increment counter
    if (count === 0) {
      // First request in window
      await redis.setex(key, limit.window, 1);
    } else {
      await redis.incr(key);
    }

    // Add rate limit headers
    res.set({
      'X-RateLimit-Limit': limit.max,
      'X-RateLimit-Remaining': limit.max - count - 1,
      'X-RateLimit-Reset': Date.now() + (await redis.ttl(key) * 1000)
    });

    next();
  } catch (error) {
    console.error('Rate limit error:', error);
    // Fail open - allow request if rate limiting fails
    next();
  }
}

app.use(customRateLimit);
```

**5. Progressive Delay Implementation:**

```javascript
const Redis = require('ioredis');
const redis = new Redis();

async function progressiveRateLimit(req, res, next) {
  const identifier = req.ip;
  const key = `failed_attempts:${identifier}`;

  try {
    const attempts = await redis.get(key);
    const failCount = attempts ? parseInt(attempts) : 0;

    // Calculate delay based on failures
    const delays = [0, 2000, 5000, 15000, 60000]; // milliseconds
    const delay = delays[Math.min(failCount, delays.length - 1)];

    if (delay > 0) {
      await new Promise(resolve => setTimeout(resolve, delay));
    }

    // Store original end function
    const originalEnd = res.end;

    // Override end to track failures
    res.end = function(...args) {
      if (res.statusCode === 401 || res.statusCode === 400) {
        // Failed attempt
        redis.incr(key);
        redis.expire(key, 3600); // Reset after 1 hour
      } else if (res.statusCode === 200) {
        // Success - reset counter
        redis.del(key);
      }

      originalEnd.apply(res, args);
    };

    next();
  } catch (error) {
    console.error('Progressive rate limit error:', error);
    next();
  }
}

app.post('/login', progressiveRateLimit, (req, res) => {
  // Login logic
});
```

