```javascript
const express = require('express');
const rateLimit = require('express-rate-limit');
const RedisStore = require('rate-limit-redis');
const Redis = require('ioredis');
const winston = require('winston');

const app = express();

// Logger setup
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'rate-limit.log' })
  ]
});

// Redis client
const redisClient = new Redis({
  host: process.env.REDIS_HOST,
  port: process.env.REDIS_PORT,
  password: process.env.REDIS_PASSWORD,
  retryStrategy: (times) => {
    const delay = Math.min(times * 50, 2000);
    return delay;
  }
});

// Handle Redis errors
redisClient.on('error', (err) => {
  logger.error('Redis error:', err);
});

// Create rate limiter with comprehensive options
const createLimiter = (options) => {
  return rateLimit({
    store: new RedisStore({
      client: redisClient,
      prefix: `rl:${options.name}:`,
    }),
    windowMs: options.windowMs,
    max: options.max,
    standardHeaders: true,
    legacyHeaders: false,
    skipSuccessfulRequests: options.skipSuccessful || false,
    keyGenerator: (req) => {
      return req.user?.id || req.ip;
    },
    handler: (req, res, next, options) => {
      // Log rate limit violation
      logger.warn('Rate limit exceeded', {
        ip: req.ip,
        path: req.path,
        user: req.user?.id,
        limit: options.max,
        windowMs: options.windowMs
      });

      res.status(429).json({
        error: 'Too many requests',
        message: options.message,
        retryAfter: Math.ceil(options.windowMs / 1000)
      });
    },
    skip: (req) => {
      // Skip for health checks
      return req.path === '/health';
    },
    onLimitReached: (req, res, options) => {
      // Alert on repeated violations
      logger.error('Rate limit reached', {
        ip: req.ip,
        path: req.path,
        user: req.user?.id
      });
    }
  });
};

// Different limiters for different endpoints
const loginLimiter = createLimiter({
  name: 'login',
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessful: true,
  message: 'Too many login attempts. Please try again in 15 minutes.'
});

const formLimiter = createLimiter({
  name: 'form',
  windowMs: 60 * 60 * 1000,
  max: 30,
  message: 'Too many form submissions. Please try again later.'
});

const apiLimiter = createLimiter({
  name: 'api',
  windowMs: 60 * 60 * 1000,
  max: 1000,
  message: 'API rate limit exceeded.'
});

// Apply limiters
app.post('/login', loginLimiter, (req, res) => {
  // Login logic
});

app.post('/submit-form', formLimiter, (req, res) => {
  // Form logic
});

app.use('/api', apiLimiter);

// Global fallback limiter
app.use(createLimiter({
  name: 'global',
  windowMs: 60 * 60 * 1000,
  max: 500,
  message: 'Too many requests.'
}));

// Error handling
app.use((err, req, res, next) => {
  logger.error('Application error:', err);
  res.status(500).json({ error: 'Internal server error' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

